### Contoh

Menulis banyak data sambil menghormati backpressure:

```js
import { once } from 'node:events';

for (const baris of semuaBaris) {
  if (!out.write(baris)) {
    await once(out, 'drain'); // tunggu penampung kosong
  }
}
out.end();
```

Kabar baiknya: `pipeline` dan `for await` **sudah menangani backpressure otomatis**. Kamu hanya perlu memikirkannya saat memanggil `write()` sendiri di dalam loop.

cards.code:
import { Writable } from 'node:stream';
import { once } from 'node:events';

let diterima = 0;
const lambat = new Writable({
  highWaterMark: 4,
  write(potongan, enc, cb) {
    diterima += potongan.length;
    setTimeout(cb, 2);
  },
});
console.log(lambat.write('ab'), lambat.write('cd'), lambat.write('ef'));
await once(lambat, 'drain');
console.log('drain, diterima', diterima);

let tunggu = 0;
for (const s of ['gh', 'ij', 'kl', 'mn', 'op']) {
  if (!lambat.write(s)) {
    tunggu++;
    await once(lambat, 'drain');
  }
}
lambat.end();
await once(lambat, 'finish');
console.log('selesai, diterima', diterima, 'menunggu', tunggu, 'kali');

