import { Writable } from 'node:stream';
import { once } from 'node:events';
const w = new Writable({ highWaterMark: 2, write(c, e, cb) { setTimeout(cb, 1); } });
for (const s of ['x', 'y', 'z']) {
  if (!w.write(s)) await once(w, 'drain');
}
w.end();
await once(w, 'finish');
console.log('Selesai');
